export const ENEMY_RESKIN = {"scarecrow":{"name":"폐기 마네킹 잡령","blurb":"훈련장에 버려진 표적 마네킹에 잡령이 들었다. 움직임이 단순하다.","special":"혼 흡입"},"snake":{"name":"케이블 구렁이","blurb":"폐통신관 속에서 몸을 부풀려 덮치는 구렁이. 비늘 대신 피복이 벗겨져 있다.","special":"결박"},"wonhon":{"name":"미삭제 원귀","blurb":"삭제 요청이 처리되지 않아 서버에 남은 원한. 오래 묵어 한 방이 무겁다.","special":"원한 루프"},"foxfire":{"name":"여우불 군집","blurb":"밤길에 여우 울음 같은 노이즈를 내며 떠도는 푸른 플라스마 무리. 혼자서는 벅차다.","special":"불똥 산포"},"dueoksini":{"name":"두억시니 압류체","blurb":"어둠 속에서 사람을 짓누르는 사나운 야차. 관리국 분류 등급 ‘둘 이상 대응’.","special":"가압 그림자"},"bulgasari":{"name":"불가살이 포식체","blurb":"쇠붙이를 먹고 자라는 괴수. 폐차장 하나를 삼키고도 배가 고프다.","special":"금속 침식","special2":"용광 분사"},"geuseundae":{"name":"그슨대 증폭체","blurb":"올려다볼수록 커지는 그림자 거인. 관측할수록 출력이 오른다.","special":"압착","special2":"암막 전개"},"mongdangbi":{"name":"몽당비 드로이드","blurb":"닳고 닳은 청소 드로이드에 도깨비가 들었다. 쓸어 담는 것은 먼지만이 아니다.","special":"로그 쓸어내기"},"yagwanggwi":{"name":"야광귀 스캐너","blurb":"설날 밤 집집이 내려와 신발을 스캔해 가는 귀신. 신을 잃은 사람은 그해 운이 없다.","special":"주머니 탈취"},"dalgyal-gwisin":{"name":"무안면 귀신","blurb":"눈도 코도 입도 없는 매끈한 얼굴. 안면 인식이 영원히 ‘검색 중’에 머문다.","special":"빈 얼굴"},"dungap-jwi":{"name":"둔갑쥐 떼","blurb":"사람의 생체 정보를 주워 먹고 사람 흉내를 내게 된 쥐들. 한 마리씩은 약하다.","special":"군체 호출"},"kim-seobang":{"name":"김서방 도깨비","blurb":"메밀묵이라면 사족을 못 쓰는 덩치 큰 도깨비. 마주친 사람마다 씨름을 건다.","special":"메치기","special2":"도깨비방망이"},"mangtae-halabeom":{"name":"망태 수거꾼","blurb":"해 질 녘까지 밖을 쏘다니는 아이를 망태기에 담아 간다는 노인. 망태기 속은 통신 음영이다.","special":"일몰 경보"},"mongdal-gwisin":{"name":"몽달 잔류체","blurb":"짝 없이 죽은 총각의 넋. 서러움이 오래 묵어 지나가는 이에게 들러붙는다.","special":"부착"},"dokgak-gwi":{"name":"외각 도깨비","blurb":"다리가 하나뿐인 도깨비. 유압 다리로 껑충 뛰어 온몸으로 내리찍는다.","special":"단각 도약"},"gaekgwi":{"name":"객귀 떼","blurb":"길에서 죽어 제삿밥 한 번 못 얻어먹은 떠돌이 넋들. 사람 냄새에 몰려든다.","special":"넋 교환"},"jangsanbeom":{"name":"장산범","blurb":"흰 털을 휘날리는 범. 아는 이의 목소리를 합성해 사람을 부른다.","special":"음성 위조","special2":"백모 향"},"heokkaebi":{"name":"허깨비 홀로","blurb":"있는 듯 없는 듯 어른거리는 헛것. 베어도 흩어졌다가 다시 모인다.","special":"허상 투사"},"daemang":{"name":"대망이","blurb":"천 년을 묵고도 용이 되지 못한 큰 구렁이. 그 한을 사람을 삼켜 달랜다.","special":"통째 삼킴"},"songaksi":{"name":"손각시","blurb":"시집 못 가고 죽은 처녀의 넋. 밤마다 우는 소리가 주파수째로 기운을 깎는다.","special":"비탄 주파"},"imae-mangryang":{"name":"이매망량","blurb":"산의 정령 이매와 물의 정령 망량. 늘 짝을 지어 길 잃은 사람을 홀린다.","special":"산수 동기화"},"cheonnyeon-jine":{"name":"천년지네","blurb":"제물을 받아 온 천 년 묵은 지네. 마디마다 독이 순환한다.","special":"독니","special2":"독무"},"changgwi":{"name":"창귀","blurb":"범에게 먹힌 뒤 범의 종이 된 귀신. 다음 먹잇감의 위치를 범에게 전송한다.","special":"범 호출"},"myogwi":{"name":"묘귀","blurb":"아홉 번 죽고 아홉 번 되살아난 고양이 귀신. 소리 없이 다가와 할퀸다.","special":"열상"},"jeokwi":{"name":"저퀴 감염체","blurb":"사람 몸에 붙어 병을 옮기는 귀신. 한 번 들러붙으면 떨어지지 않는다.","special":"전염"},"agwi":{"name":"아귀 떼","blurb":"목구멍이 바늘구멍만 해 아무리 먹어도 배가 차지 않는 굶주린 넋들.","special":"약자 우선"},"geumdwaeji":{"name":"금돼지","blurb":"땅속 굴에 사는 금빛 돼지. 사람을 잡아 가두며, 금속이라면 눈이 뒤집힌다.","special":"엄니 충전","special2":"금빛 공명"},"gildal":{"name":"길달","blurb":"귀신 무리에서 달아나 여우로 둔갑한 자. 몰리면 모습을 바꾼다.","special":"둔갑 위장"},"jigwi":{"name":"지귀","blurb":"이룰 수 없는 사랑에 가슴이 타 불귀신이 된 사내. 지나간 자리가 그을린다.","special":"연모 발화"},"gawi-gwi":{"name":"가위귀","blurb":"잠든 사람의 가슴 위에 올라앉는 귀신. 깨어 있어도 그 무게는 사라지지 않는다.","special":"수면 마비"},"udu-mamyeon":{"name":"우두마면","blurb":"소머리 우두와 말머리 마면. 명부에서 망자를 끌고 가는 두 집행관.","special":"명부 사슬"},"gumiho":{"name":"구미호","blurb":"천 년을 묵어 꼬리가 아홉 갈래인 여우. 사람의 기운을 받아먹는다.","special":"여우구슬","special2":"꼬리 소각"},"yeou-nui":{"name":"여우누이","blurb":"오래 기다려 얻은 막내딸이 실은 여우였다. 밤마다 축사의 짐승이 한 마리씩 죽는다.","special":"누이 얼굴"},"noho-seung":{"name":"노호승","blurb":"승려의 탈을 쓰고 경을 외는 늙은 여우. 그 독경은 몸속 영력을 거꾸로 돌린다.","special":"역독경"},"chokru-gwi":{"name":"촉루귀","blurb":"들판에 버려진 해골들이 엉겨 일어선 귀신. 부딪칠 때마다 뼈가 운다.","special":"골격 재조립"},"bulgae":{"name":"불개","blurb":"까막나라 임금이 해와 달을 훔쳐 오라고 보낸 개. 물수록 힘이 붙는다.","special":"일월 포식"},"yeoksin":{"name":"역신","blurb":"마을마다 돌림병을 퍼뜨리는 귀신. 병이 번질수록 몸집도 커진다.","special":"역병","special2":"돌림병"},"geuseunsae":{"name":"그슨새","blurb":"그슨대가 새의 모습을 한 것. 커다란 날개로 하늘을 덮는다.","special":"날개 암막"},"hwama":{"name":"화마","blurb":"불길 속에서 태어나 불길로 사는 마귀. 건물 한 채를 삼키는 데 숨 한 번이면 된다.","special":"연소 전이"},"yeongno":{"name":"영노","blurb":"아흔아홉을 먹고 하나만 더 먹으면 하늘에 오른다는 괴물. 그 하나가 당신이다.","special":"아흔아홉째"},"yacha-nachal":{"name":"야차나찰","blurb":"하늘을 나는 야차와 사람을 먹는 나찰. 한 쌍의 칼처럼 붙어 다닌다.","special":"쌍검 무장해제"},"hanbal":{"name":"한발","blurb":"나타나면 비가 그치고 강이 마르는 가뭄의 마귀.","special":"갈증","special2":"가뭄의 해"},"gangcheol":{"name":"강철이","blurb":"용이 되다 만 괴수. 지나가는 곳마다 들판이 하룻밤 새 마른다.","special":"건조풍"},"mudu-gwi":{"name":"무두귀","blurb":"머리 없이 떠도는 귀신. 잃어버린 머리를 찾아 닥치는 대로 붙잡는다.","special":"머리 탐색"},"gwimok":{"name":"귀목","blurb":"사람의 피를 빨아 천 년을 자란 고목. 뿌리가 닿는 곳마다 풀이 시든다.","special":"수피 장갑"},"baekgwi":{"name":"백귀야행","blurb":"깊은 밤 길을 지나가는 백 가지 귀신의 행렬. 마주친 사람은 행렬에 끼게 된다.","special":"행렬 편입"},"samdugumi":{"name":"삼두구미","blurb":"머리 셋, 꼬리 아홉의 괴물. 무덤을 파헤쳐 송장을 먹는다.","special":"삼두 연격","special2":"꼬리의 원한"},"baekgol-janggun":{"name":"백골장군","blurb":"옛 싸움터의 백골이 녹슨 갑옷을 걸치고 일어섰다. 북소리가 울리면 부서진 병사들이 따라 선다.","special":"방패진"},"yohwa":{"name":"요화","blurb":"무덤가에 피어 망자의 피를 먹고 자란 핏빛 꽃. 꽃가루가 신경을 마비시킨다.","special":"마비 화분"},"daein":{"name":"대인","blurb":"구름 위로 머리가 솟는 거인. 걸음 한 번에 산 하나를 넘는다.","special":"거족 낙하"},"gunggi":{"name":"궁기","blurb":"날개 달린 범 모습의 흉수. 싸움을 말리는 자를 먼저 먹는다.","special":"이간"},"jihaguk-daejeok":{"name":"지하국 대적","blurb":"땅 밑 나라를 다스리는 머리 아홉의 도적. 땅 위의 사람을 잡아다 부린다.","special":"두부 투척","special2":"구두 기동"},"cheonma":{"name":"천마","blurb":"하늘 끝의 마왕. 수행하는 자의 앞을 가로막고, 깨달음에 가까울수록 강해진다.","special":"마왕의 거울"},"doul":{"name":"도올","blurb":"말을 듣지 않고 길들일 수도 없는 흉수. 범의 몸에 사람의 얼굴.","special":"폭주"},"geoul-gwi":{"name":"명두귀","blurb":"무당의 청동거울 명두에 깃든 귀신. 비친 기운을 그대로 빼앗는다.","special":"되비춤"},"hondon":{"name":"혼돈","blurb":"눈도 코도 입도 귀도 없는 흉수. 일곱 구멍을 뚫어 주자 이레 만에 죽었다던 그것.","special":"칠규 교란"},"docheol":{"name":"도철","blurb":"먹는 것밖에 모르는 흉수. 무엇이든 삼키다 끝내 제 몸까지 먹어 치운다.","special":"결계 포식","special2":"무한 허기"}}
export const PSYCHIC_RESKIN = {"buff":{"label":"신명 증폭","note":"누구나 태어날 때부터 가진 영능력. 몸에 흐르는 신명을 한 박자 끌어올린다."},"survival":{"label":"생존 프로토콜","note":"불리하다고 판단되면 적을 교란하고 이탈한다. 후일을 도모하는 것도 살아남은 자의 특권이다."},"cotton-mist":{"label":"백무 산포","note":"손끝에서 피어오르는 흰 안개. 적의 눈을 가리고 감정과 상태를 주무른다."},"echo-form":{"label":"기억 구현","note":"가장 안전하고 평화로웠던 기억을 불러내 형체로 만든다. 돌아갈 수 없다면 지금을 지켜."},"falling-light":{"label":"강림광","note":"스스로 내뿜은 빛에 앞이 보이지 않는다. 할 수 있는 것은 웅크리는 것뿐. 그것으로 충분하다."},"monkey-paw":{"label":"등가 교환","note":"얻는 만큼 잃는다. 영구히 얻고자 하면 영구히 잃는다."},"dokkaebi-fire":{"label":"도깨비불","note":"어딘가에 홀연히 나타나는, 혼을 먹고 자란다는 푸른 불꽃."},"karmic-recompense":{"label":"업보 연산","note":"원하지 않아도 업이 쌓이는 세계에서, 자신이 쌓을 업을 스스로 고를 수 있다는 것은 행운이다."},"earth-step":{"label":"지신밟기","note":"이곳은 절대적으로 안전하다. 거대한 무언가가 모두를 지키고 있다."},"warding-scripture":{"label":"벽사진경","note":"사악한 것은 쫓아내고 복된 것은 맞이한다. 전투를 굿판처럼 벌여 보자."},"spirit-barrier":{"label":"영력 결계","note":"볼 수 없다는 것은 축복이요, 볼 수 있다는 것은 저주라. 앎은 영혼을 얽매고 무지는 목을 조른다."},"seven-stars":{"label":"칠성 각인","note":"북두칠성의 기운을 새긴다. 은하수처럼 흐르고 폭포수처럼 쏟아진다."},"language-barrier":{"label":"통역 장벽","note":"사람도 짐승도 넋도 태어나기 전의 세계는 하나. 뜻이 통하면 읽을 수 있으리."}}
